class Solution {
public:
    std::vector<int> evenOddBit(int n) {
        int even = 0, odd = 0;
        int idx = 0;
        while (n > 0) {
            if (n & 1) {
                if (idx % 2 == 0) even++;
                else odd++;
            }
            n >>= 1;
            idx++;
        }
        return {even, odd};
    }
};

class Solution {
    public int[] evenOddBit(int n) {
        int even = 0, odd = 0;
        int idx = 0;
        while (n > 0) {
            if ((n & 1) == 1) {
                if (idx % 2 == 0) even++;
                else odd++;
            }
            n >>= 1;
            idx++;
        }
        return new int[]{even, odd};
    }
}

